package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.util.List; public final class SessionService { private final OperationsService ops; public SessionService(OperationsService ops){this.ops=ops;} public List<String> reservations()throws Exception{return ops.eligibleReservationRecords();} public List<String> active()throws Exception{return ops.activeSessionRecords();} public List<String> customers()throws Exception{return ops.walkInCustomerRecords();} public List<String> stations()throws Exception{return ops.availableStationRecords();} public long startReserved(long a,long r)throws Exception{return ops.startSession(a,r);} public long startWalkIn(long a,long c,long s,int m)throws Exception{return ops.startWalkInSession(a,c,s,m);} public void extend(long a,long s,int m)throws Exception{ops.extendSession(a,s,m);} public long finish(long a,long s)throws Exception{return ops.finishSessionCalculated(a,s);} public String bill(long s)throws Exception{return ops.sessionBill(s);} }